#pragma once
// compiled-in biome data: where biomes go (Java's overworld placement table) and what they are made of (bedrock-samples' surface builders).
// generated by tools/gen_biome_tables.py
#include <cstdint>

namespace perlin::server::vanilla {

    // one biome of the table, in Java's names with its Bedrock counterpart's materials
    struct BiomeMaterials {
        const char* java;
        const char* bedrock;
        const char* top;
        const char* mid;
        const char* foundation;
        const char* seaFloor;
        const char* sea;
        int seaFloorDepth;
        // 0 overworld, 1 frozen ocean, 2 mesa, 3 swamp (the builder types that apply to the overworld)
        int builder;
    };

    constexpr int kBiomePointStride = 13;
    extern const int kBiomePointCount;
    extern const int16_t kBiomePointData[];
    extern const uint8_t kBiomePointBiome[];
    extern const int kBiomeCount;
    extern const BiomeMaterials kBiomes[];
}
